const item = $input.first(); // first incoming item
const text = item.json.output;
// Remove markdown code fences like ```json and ```
const cleaned = text
  .replace(/^```json\s*/i, "")
  .replace(/```$/i, "")
  .trim();

let outlineObj;
try {
  outlineObj = JSON.parse(cleaned);
} catch (e) {
 return [{
    json: {
      error: true,
      error_type: 'SEO_JSON_PARSE_FAILED',
      raw_output: cleaned
    }
  }];
}

return [
  {
    json: {
      title: outlineObj.title,
      content: outlineObj.content,
      error: false
    }
  }
];

